\label{remark supercritical MFP}
For the MFP model it is the case  that, for $p>\ensuremath{p_{c}(d)}$,
\begin{equation}\label{prob to 1}
\sigma(p,N,d) \to 1,  
\end{equation}
as $N \to \infty$. This is part (b) of Theorem 2 in \cite{FalGri}. During the course of the proof of Theorem \ref{thm critical k} we will prove a similar result for the $k$-model, see Theorem \ref{thm supercritical}.

\label{thm lebesgue}
Given non-extinction of the fat fractal process, it is the case that either 
\begin{equation}\label{fat con}
\lambda(\ensuremath{D_{\text{fat}}^{d}}) =0 \text{ and } \lambda(\ensuremath{D_{\text{fat}}^{c}})>0 \text{ a.s.}                                                                              
\end{equation}
 or
\begin{equation}\label{fat dust}
\lambda(\ensuremath{D_{\text{fat}}^{d}}) >0 \text{ and } \lambda(\ensuremath{D_{\text{fat}}^{c}})=0 \text{ a.s.}
\end{equation}

\label{thm charac} We have that
\begin{itemize}
 \item[$(i)$] If $\prod_{n=1}^{\infty} p_n^{N^{dn}} = 0$, then $\ensuremath{D_{\text{fat}}}$ has an empty interior a.s.;
\item[$(ii)$] If $\prod_{n=1}^{\infty} p_n^{N^n} > 0$, then $\lambda(\ensuremath{D_{\text{fat}}^{d}}) = 0$ a.s.;
\item[$(iii)$] If $\prod_{n=1}^{\infty} p_n^{N^{dn}} > 0$, then $\ensuremath{D_{\text{fat}}}$ can be written as the union of finitely many cubes a.s.
\end{itemize}

 \label{thm pos prob} Let $d=2$. The following statements are equivalent.
\begin{itemize}
 \item[$(i)$] $\lambda(D^c_{\text{fat}}) > 0$ a.s., given non-extinction of the fat fractal process;
\item[$(ii)$] There exists a set $U\subset [0,1]^2$ with $\lambda(U)>0$ such that for all $x,y \in U$ it is the case that $\ensuremath{\mathbb{P}}( x \text{ is in the same connected component as } y) >0$;
\item[$(iii)$] There exists a set $U\subset [0,1]^2$ with $\lambda(U)=1$ such that for all $x,y \in U$ it is the case that $\ensuremath{\mathbb{P}}( x \text{ is in the same connected component as } y) >0$.
\end{itemize}

\label{lem FalGri}
 Suppose $\pi>\ensuremath{p_{c}(d)}, \epsilon>0$ and let $q$ be a positive integer. There exist positive integers $u$ and $N_1$ such that the following holds for all $N \geq N_1$. Let $U(1),\ldots,U(q)$ be subsets of vertices of $B_N$ such that for each $r\in\{1,\ldots,q\}$, (i) $|U(r)| \geq u$ and (ii) there exists $L \in \ensuremath{\mathcal{L}}$ such that $U(r) \subset L_N$. Then, 
\begin{equation}\label{perc bound}
 P_{\pi}\left(\begin{array}{c}
      \text{there exists a black cluster } C_N \text{ such that }|C_N \cap L_N| \geq u \\
      \text{ for all } L \in \ensuremath{\mathcal{L}}, \text{ and } | C_N \cap U(r)| \geq 1, \text{ for all } r\in\{1,\ldots,q\} \end{array}\right) \geq 1- \frac{\epsilon}{2}.
\end{equation}

 \label{lem prob}
Let $p> \ensuremath{p_{c}(d)}$ and let $(k(N))_{N \geq 2}$ be a sequence of integers such that $k(N)/N^{d} \geq  p$, for all $N \geq 2$. Let $\epsilon>0$ be such that $(1-\epsilon)p>\ensuremath{p_{c}(d)}$. Take $\pi \in (\ensuremath{p_{c}(d)}, (1-\epsilon)p)$ and set $q=3^d$. Let $u$ and $N_1$ be given by Lemma \ref{lem FalGri}. Let $N_2$ be given by Lemma \ref{lem good3}.  Set $N_0 =\max\{N_1,N_2\}$. Then, for all $n \geq 1$,
\begin{equation}\label{unit cube good}
 \ensuremath{\mathbb{P}}_{k(N)}([0,1]^d \text{ is } (n,u)\text{-good}) \geq 1-\epsilon,
\end{equation}
for all $N \geq N_0$.

Fix $N \geq N_0$ and $n\geq 1$ and consider the $k(N)$-fractal model. Our aim is to show that 
\begin{equation}\label{induction2}
 \ensuremath{\mathbb{P}}_{k(N)}(C(\ensuremath{\mathbf{I}}) \text{ is } (n,u)\text{-good} \mid \ensuremath{\mathcal{F}}(\ensuremath{\mathbf{I}}^-)) \geq 1 -\epsilon
\end{equation}
holds for all $\ensuremath{\mathbf{I}} \in \ensuremath{\mathcal{J}}^{(n)}$. Taking $\ensuremath{\mathbf{I}}=\emptyset$ then yields \eqref{unit cube good}. We prove this with a recursive argument. Let $\ensuremath{\mathbf{I}}_0$ be the smallest index in $\ensuremath{\mathcal{J}}^{(n)}$, according to the ordering on $\ensuremath{\mathcal{J}}^{(n)}$. By virtue of the ordering, we have $|\ensuremath{\mathbf{I}}_0| = n$. Hence, by definition, $C(\ensuremath{\mathbf{I}}_0)$ is $(n,u)$-good. In particular, \eqref{induction2} holds for $\ensuremath{\mathbf{I}}_0$.


The recursive step is as follows. Take an index $\ensuremath{\mathbf{I}} \in \ensuremath{\mathcal{J}}^{(n)}$ and assume that  
\begin{equation}\label{induction}
 \ensuremath{\mathbb{P}}_{k(N)}(C(\ensuremath{\mathbf{I}}') \text{ is } (n,u)\text{-good} \mid \ensuremath{\mathcal{F}}(\ensuremath{\mathbf{I}}'^-)) \geq 1 -\epsilon,
\end{equation}
has been established for all indices $\ensuremath{\mathbf{I}}'$ in $\ensuremath{\mathcal{J}}^{(n)}$ less than $\ensuremath{\mathbf{I}}$. We have to show that \eqref{induction2} holds for $\ensuremath{\mathbf{I}}$ given this assumption. We have two cases:
\begin{itemize}
 \item[(a)] $|\ensuremath{\mathbf{I}}| =n$; then $\ensuremath{\mathbb{P}}_{k(N)}(C(\ensuremath{\mathbf{I}}) \text{ is } (n,u)\text{-good}) =1$ and \eqref{induction2} is true.
\item[(b)] $0 \leq |\ensuremath{\mathbf{I}}| = m < n$.
\end{itemize}


For case (b), given $\ensuremath{\mathcal{F}}(\ensuremath{\mathbf{I}}^-)$, the goodness of $C(\ensuremath{\mathbf{I}}')$ is determined (in particular) for all $\ensuremath{\mathbf{I}}' < \ensuremath{\mathbf{I}}$ with $|\ensuremath{\mathbf{I}}|=m$. Let
\begin{eqnarray*}
 \ensuremath{\mathcal{Q}}=\left\{\begin{array}{cc} \ensuremath{\mathbf{I}}': & \ensuremath{\mathbf{I}}'<\ensuremath{\mathbf{I}} \text{ and } C(\ensuremath{\mathbf{I}}') \text{ is an } (n,u)\text{-good level-}m \\
& \text{ cube with an edge in common with }C(\ensuremath{\mathbf{I}})           
          \end{array}\right\}.
\end{eqnarray*}
For each $\ensuremath{\mathbf{I}}' \in \ensuremath{\mathcal{Q}}$, let $E(\ensuremath{\mathbf{I}}')$ be some common edge of $C(\ensuremath{\mathbf{I}})$ and $C(\ensuremath{\mathbf{I}}')$. Since $C(\ensuremath{\mathbf{I}}')$ is $(n,u)$-good, there are at least $u$ level-$(m+1)$ subcubes in $\ensuremath{\mathcal{H}}(\ensuremath{\mathbf{I}}')$ which intersect $E(\ensuremath{\mathbf{I}}')$; call this set of subcubes $\ensuremath{\mathcal{U}}(\ensuremath{\mathbf{I}}')$. To see whether $C(\ensuremath{\mathbf{I}})$ is $(n,u)$-good, we look at $C(\ensuremath{\mathbf{I}},\ensuremath{\mathbf{j}}(l))$ where $\ensuremath{\mathbf{j}}(l), 1 \leq l \leq N^d,$ are the vectors of $J^d$ arranged in order. We have $(\ensuremath{\mathbf{I}},\ensuremath{\mathbf{j}}(l)) < \ensuremath{\mathbf{I}}$, so by the induction hypothesis \eqref{induction} we have
\begin{equation}\label{induction sub}
 \ensuremath{\mathbb{P}}_{k(N)}(C(\ensuremath{\mathbf{I}},\ensuremath{\mathbf{j}}(l)) \text{ is } (n,u)\text{-good} \mid \ensuremath{\mathcal{F}}((\ensuremath{\mathbf{I}},\ensuremath{\mathbf{j}}(l))^-)) \geq 1-\epsilon,
\end{equation}
for all $l$. Note that $\ensuremath{\mathcal{F}}((\ensuremath{\mathbf{I}},\ensuremath{\mathbf{j}}(1))^-) = \ensuremath{\mathcal{F}}(\ensuremath{\mathbf{I}}^-)$.


We identify each subcube of $C(\ensuremath{\mathbf{I}})$ in the canonical way with a vertex in $B_N$. We will construct three random subsets $G_1, G_2, G_3$ of $B_N$ on a common probability space with the following properties:
\begin{itemize}
\item[(I)] the law of $G_1$ equals the law of the set of subcubes $C(\ensuremath{\mathbf{I}},\ensuremath{\mathbf{j}})$ of $C(\ensuremath{\mathbf{I}})$ which are $(n,u)$-good and satisfy $Z_{k(N)}(\ensuremath{\mathbf{I}},\ensuremath{\mathbf{j}})=1$;
\item[(II)] $G_2$ is obtained by first selecting $k(N)$ vertices of $B_N$ uniformly and then retaining each selected vertex with probability $1-\epsilon$, independently of other vertices;
\item[(III)] the law of $G_3$ is the Bernoulli product measure with density $\pi$ on $B_N$;
\item[(IV)] $G_1 \supset G_2$;
\item[(V)] $\ensuremath{\mathbb{P}}(G_2 \supset G_3) \geq 1-\epsilon/2$.
\end{itemize}


From \eqref{induction sub} and a standard coupling technique, sometimes referred to as sequential coupling (see e.g.\ \cite{LigSte}), the construction of $G_1$ and $G_2$ with properties (I), (II) and (IV) is straightforward. The construction of $G_3$ such that properties (III) and (V) hold is given below. Let $|G_2|$ denote the cardinality of the set $G_2$. Define $M=((1-\epsilon)p+\pi)N^d / 2$ and let $R$ be a number drawn from a binomial distribution with parameters $N^d$ and $\pi$, independently of $G_1$ and $G_2$. If $|G_2| \geq M$ and $M\geq R$ we select $R$ vertices uniformly  out of the $|G_2|$ retained vertices of $G_2$ and call this set $G_3$. Otherwise, we select, independently of $G_1$ and $G_2$, $R$ vertices of $B_N$ in a uniform way and call this set $G_3$. From the construction (note that also $G_2$ was obtained in a uniform way) it is clear that $G_3$ satisfies property (III). Observe that $|G_2|$ has a binomial distribution with parameters $k(N)$ and $1-\epsilon$. From Lemma \ref{lem good3} it follows that
\[
 \ensuremath{\mathbb{P}}(\{|G_2| \geq M \} \cap \{R \leq M\}) \geq 1-\epsilon/2.
\]
Hence, property (V) also holds.


Let us now return to the goodness of $C(\ensuremath{\mathbf{I}})$. As before, we identify the random subsets $G_1,G_2,G_3$ of $B_N$ with
the corresponding sets of subcubes  of $C(\ensuremath{\mathbf{I}})$ in the canonical way. It then follows from property (III) and Lemma \ref{lem FalGri} (note that $\ensuremath{\mathcal{Q}}$ has cardinality at most $3^d =q$) that $G_3$ has an edge-connected subset which satisfies the following properties with probability at least $1-\epsilon/2$:
\begin{itemize}
  \item[(i)] intersects every edge of $C(\ensuremath{\mathbf{I}})$ with at least $u$ cubes;
 \item[(ii)] contains a cube that is edge-connected to a cube of $\ensuremath{\mathcal{U}}(\ensuremath{\mathbf{I}}')$, for all $\ensuremath{\mathbf{I}}' \in \ensuremath{\mathcal{Q}}$. 
 \end{itemize}


Combining properties (IV), (V) and the previous paragraph we obtain
\begin{eqnarray*}
 \lefteqn{\ensuremath{\mathbb{P}}_{k(N)}(C(\ensuremath{\mathbf{I}}) \text{ is } (n,u)\text{-good} \mid \ensuremath{\mathcal{F}}(\ensuremath{\mathbf{I}}^-))} \\
& \geq& \ensuremath{\mathbb{P}}(\{G_1 \supset G_3 \} \cap \{G_3 \text{ satisfies properties (i) and (ii)}\}) \\
&\geq& 1-\epsilon.
\end{eqnarray*}
Therefore, \eqref{induction2} holds for the index $\ensuremath{\mathbf{I}}$ given that \eqref{induction} holds for all indices $\ensuremath{\mathbf{I}}'<\ensuremath{\mathbf{I}}$. A recursive use of this argument -- recall that \eqref{induction2} is valid for $\ensuremath{\mathbf{I}}_0$ (the smallest index according to the ordering) -- yields that \eqref{induction2} holds for all $\ensuremath{\mathbf{I}}$. Taking $\ensuremath{\mathbf{I}}=\emptyset$ in \eqref{induction2} proves the lemma.

We use the idea of the proof of Theorem \ref{thm subcritical} and the result of Theorem \ref{thm supercritical}. Fix some $p_0$ such that $\ensuremath{p_{c}(d)}<p_0 < p$ and set $k(N):=\lfloor p_0 N^d \rfloor$. Consider the event $F$ that in the GFP model with generator $Y = Y(N,d)$ there exists an infinite tree of retained subcubes such that each subcube in the tree contains at least $k(N)$ retained subcubes in the tree. Similar to the proof of Lemma \ref{lem high prob}, we prove that $\ensuremath{\mathbb{P}}(F)\to 1$ as $N\to\infty$. We then show that the law of $D_{k(N)}$ is stochastically dominated by the conditional law of $D_Y$, conditioned on the event $F$. By Theorem \ref{thm supercritical} we can then conclude that $\phi(Y(N,d),N,d) \to 1$ as $N \to \infty$. 


Consider the construction of $D_{Y}$. We will use the same definition of $m$-good as in Section \ref{sec subcritical}, that is, if a level-$n$ cube is retained and contains at least $k(N)$ retained subcubes, we call this level-$n$ cube 0-good. Recursively, we say that a level-$n$ cube is $(m+1)$-good if it is retained and contains at least $k(N)$ $m$-good level-$(n+1)$ subcubes. We call the unit cube $\infty$-good if it is $m$-good for every $m \geq 0$. Define the following events
\begin{eqnarray*}
 F_m:=\{[0,1]^d \text{ is }m\text{-good}\},\\
F:=\{[0,1]^d \text{ is }\infty\text{-good}\}.
\end{eqnarray*}


We will show that for every $\epsilon>0$ such that $(1-\epsilon)p > p_0$ there exists $N_0=N_0(\epsilon)$ such that, for all $m \geq 0$,
\begin{equation}\label{claim m-good}
\ensuremath{\mathbb{P}}(F_m) > 1-\epsilon, \quad \text{for all } N \geq N_0 .
\end{equation}


The proof of \eqref{claim m-good} is similar to the proof of Lemma \ref{lem high prob}. Let $\epsilon>0$ be such that $(1-\epsilon)p > p_0$. Take $\delta>0$ such that $(1-\epsilon)p>p_0+\delta$. Then, take $N_0$ so large that
\begin{eqnarray}
 1 - \frac{1}{4\delta^2 N} > 1-\epsilon/2 \quad \text{and} \label{delta bound}\\
\ensuremath{\mathbb{P}}(Y \geq p N^d) > 1-\epsilon/2 \label{Y bound},
\end{eqnarray}
for all $N\geq N_0$. We prove that \eqref{claim m-good} holds for this $N_0$ and all $m\geq 0$, by induction on $m$. Since $k(N) = \lfloor p_0 N^d \rfloor \leq pN^d$ it follows from \eqref{Y bound} that $\ensuremath{\mathbb{P}}(F_0)>1-\epsilon$, for all $N\geq N_0$. 


Next, assume that \eqref{claim m-good} holds for some $m\geq 0$. The probability that a level-1 cube is $m$-good, given that it is retained, is equal to $\ensuremath{\mathbb{P}}(F_m)$. It follows that, given that the number of retained level-1 cubes equals $y$, the number of $m$-good level-1 cubes has a binomial distribution with parameters $y$ and $\ensuremath{\mathbb{P}}(F_m)$. By our choices for $N_0$ and $\delta$ we get
\begin{eqnarray*}
 \ensuremath{\mathbb{P}}(F_{m+1}) &=& \sum_{y \geq k(N)} \ensuremath{\mathbb{P}}(X(y,\ensuremath{\mathbb{P}}(F_m)) \geq k(N)) \, \ensuremath{\mathbb{P}}(Y = y) \\
& \geq& \ensuremath{\mathbb{P}}(X(\lfloor pN^d \rfloor,\ensuremath{\mathbb{P}}(F_m)) \geq p_0 N^d) \, \ensuremath{\mathbb{P}}(Y \geq \lfloor pN^d \rfloor) \\
&\geq& \ensuremath{\mathbb{P}}(X(\lfloor pN^d \rfloor,1-\epsilon)\geq p_0 N^d) (1-\epsilon/2) \\
&\geq& \left(1-\frac{\ensuremath{\IV\text{ar}} X(\lfloor pN^d \rfloor,1-\epsilon)}{(p_0 - (1-\epsilon)p)^2 N^{2d}}\right)(1-\epsilon/2) \\
&\geq& \left(1-\frac{(1-\epsilon)\epsilon pN^d}{\delta^2 N^{2d}}\right) (1-\epsilon/2) \\
&\geq& \left(1-\frac{1}{4 \delta^2 N^d}\right)(1-\epsilon/2) \\
&\geq& (1-\epsilon/2)(1-\epsilon/2)>1-\epsilon,
\end{eqnarray*}
 for all $N \geq N_0$. Hence, the induction step is valid.


Analogously to the proof of Theorem \ref{thm subcritical} we use the event $F=\bigcap_{m=1}^{\infty} F_m$ to construct two random subsets $\tilde D_{k(N)}$ and $\tilde D_{Y}$ on a common probability space, with the following properties: 
\begin{itemize}
 \item[(i)] $\tilde{D}_{k(N)} \subset \tilde{D}_{Y}$;
\item[(ii)] the law of $\tilde{D}_{Y}$ is stochastically dominated by the conditional law of $D_{Y}$, conditioned on the event $F$;
\item[(iii)] the law of $\tilde D_{k(N)}$ is equal to the law of $D_{k(N)}$.
\end{itemize}
This construction is the same (modulo replacing the binomial distribution with $Y$) as in the proof of Theorem \ref{thm subcritical} and is therefore omitted.


From properties (i)-(iii) and Theorem \ref{thm supercritical} we get
\begin{eqnarray*}
 \lefteqn{\ensuremath{\mathbb{P}}([0,1]^d \text{ is crossed by } D_{Y(N,d)} | F) } \\
&\geq& \ensuremath{\mathbb{P}}([0,1]^d \text{ is crossed by } \tilde D_{Y(N,d)})  \\
&\geq & \ensuremath{\mathbb{P}}([0,1]^d \text{ is crossed by } \tilde D_{k(N)}) \\
&=&\ensuremath{\mathbb{P}}([0,1]^d \text{ is crossed by } D_{k(N)}) \to 1,
\end{eqnarray*}
as $N \to \infty$. Since \eqref{claim m-good} implies that $\ensuremath{\mathbb{P}}(F) \to 1$ as $N \to \infty$, we obtain
\[
 \ensuremath{\mathbb{P}}([0,1]^d \text{ is crossed by } D_{Y(N,d)}) \to 1,
\]
as $N \to \infty$.

First, we have to introduce some notation. Let $U$ be the collection of points in $[0,1]^d$ not on the boundary of a subcube. For each $x\in U$ there exists a unique sequence $(C({\bf x}_1,\ldots,{\bf x}_n))_{n\geq 1}$ of cubes of the fractal process, where ${\bf x}_j\in J^d$ for all $j$, such that $\bigcap_{n\geq 1} C({\bf x}_1,\ldots,{\bf x}_n) = \{ x \}$. Therefore, we can define an invertible transformation $\phi : U \to (J^d)^{\ensuremath{\mathbb{N}}}$ by $\phi(x) = ({\bf x}_1,{\bf x}_2,\ldots)$. For each $n \in \ensuremath{\mathbb{N}}$ let $\mu_n$ be the uniform measure on $(X_n,\ensuremath{\mathcal{F}}_n)$, where $X_n= J^d$ and $\ensuremath{\mathcal{F}}_n$ is the power set of $X_n$. Let $(X,\ensuremath{\mathcal{F}},\mu)=\bigotimes_{n=1}^{\infty}(X_n,\ensuremath{\mathcal{F}}_n,\mu_n)$ be the product space. Since $\phi : (U,\ensuremath{\mathcal{B}}(U),\lambda) \to (X,\ensuremath{\mathcal{F}},\mu)$ is an invertible measure-preserving transformation, we have that $(X,\ensuremath{\mathcal{F}},\mu)$ is by definition isomorphic to $(U,\ensuremath{\mathcal{B}}(U),\lambda)$. Here $\ensuremath{\mathcal{B}}(U)$ denotes the Borel $\sigma$-algebra.

Next, we define the transformation $T:U\to U$, which will play a crucial role in the rest of the proof. Define the auxiliary shift transformation $T^* : X\to X$ by $T^*(({\bf x}_1,{\bf x}_2,{\bf x}_3,\ldots)) = ({\bf x}_2,{\bf x}_3,\ldots)$, for $({\bf x}_1,{\bf x}_2,\ldots)\in X$. The transformation $T^*$ is measure preserving with respect to the measure $\mu$ and also ergodic, see for instance \cite{Wal}. Let $T := \phi^{-1} \circ T^* \circ \phi$ be the induced transformation on $U$ and note that $T$ is isomorphic to $T^*$ and hence also ergodic. Informally, $T$ sends a point $x\in U$ to the point $Tx$, in such a way that the relative position of $Tx$ in the unit cube is the same as the relative position of $x$ in its level-1 cube $C({\bf x}_1)$; see Figure \ref{fig transformation}.

\begin{figure}[!ht]
\begin{center}
\includegraphics[width=6cm]{transformation}
\caption{Illustration of the transformation $T$. Note that the relative position of $x$ in the level-1 cube is the same as the relative position of $Tx$ in the unit cube.}
\label{fig transformation}
\end{center}
\end{figure}

Recall that $\omega \in \Omega$ denotes a particular realization of the fat fractal percolation process.  For $x \in U$, we define the following event.
\[
 A^x := \left\{\omega: \text{if we set } \omega(C(\textbf{x}_1,\ldots,\textbf{x}_n)) = 1 \text{ for all } n \geq 1, \text{ then } C_{\text{fat}}^{x} \neq \{x\} \right\}.
\]
In other words, $A^{x}$ consists of those configurations $\omega$ such that when we change the configuration by retaining all $C(\textbf{x}_1,\ldots,\textbf{x}_n)$, then in this new configuration, $x$ is in the same connected component as some $y \neq x$. Observe that 
\begin{equation}\label{def A^x}
 A^x \cap \{  x\in \ensuremath{D_{\text{fat}}}\} =\{ x \in \ensuremath{D_{\text{fat}}^{c}} \}.
\end{equation}
It is easy to see that $A^{x}$ is a tail event. Hence, by Kolmogorov's 0-1 law we get $\ensuremath{\mathbb{P}}(A^{x}) \in \{0,1\}$ for all $x\in U$.

However, a priori it is not clear that for almost all $x$ in the unit cube $\ensuremath{\mathbb{P}}(A^x)$ has the same value. To this end, define the set $V:=\{x\in U: \ensuremath{\mathbb{P}}(A^{x})=0\}$. We will show that $\lambda(V)\in \{0,1\}$. Recall that the relative position of $Tx$ in the unit cube is the same as the relative position of $x$ in the level-1 cube $C(\mathbf{x}_1)$. It is possible to construct a coupling between the fractal process in the unit cube and the fractal process in $C(\mathbf{x}_1)$, given that $C(\mathbf{x}_1)$ is retained,  with the following property: For every cube $C(\ensuremath{\mathbf{I}})$ in $C(\mathbf{x}_1)$, it is the case that if $TC(\ensuremath{\mathbf{I}})$ is retained in the fractal process in the unit cube, then $C(\ensuremath{\mathbf{I}})$ is also retained in the fractal process in $C(\mathbf{x}_1)$, given that $C(\mathbf{x}_1)$ is retained. It is straightforward that such a coupling exists since the retention probabilities $p_n$ are non-decreasing in $n$. Hence,
\begin{equation}\label{A^Tx ineq}
 \ensuremath{\mathbb{P}}(A^{Tx}) \leq \ensuremath{\mathbb{P}}(A^x | C(\mathbf{x}_1) \text{ is retained}).
\end{equation}
Furthermore, since $A^x$ is a tail event, we have 
\begin{equation}\label{cond eq}
\ensuremath{\mathbb{P}}(A^x)=\ensuremath{\mathbb{P}}(A^x | C(\mathbf{x}_1) \text{ is retained}). 
\end{equation}
It follows from \eqref{A^Tx ineq} and \eqref{cond eq} that $\ensuremath{\mathbb{P}}(A^{Tx}) \leq \ensuremath{\mathbb{P}}(A^x)$ for all $x$. This implies that $V \subset T^{-1} V$. Because $T$ is measure preserving it follows that 
\[
 \lambda(V \Delta T^{-1} V) = \lambda(V \setminus T^{-1}V) + \lambda(T^{-1}V \setminus V) = 0+\lambda(T^{-1}V) - \lambda(V) = 0.
\]
Ergodicity of $T$ now yields that $\lambda(V) \in \{0,1\}$. 


Suppose $\lambda(V)=0$. Then $\ensuremath{\mathbb{P}}(x \in \ensuremath{D_{\text{fat}}^{d}})=\ensuremath{\mathbb{P}}(\{x\in \ensuremath{D_{\text{fat}}}\} \setminus A^x)=0$ for almost all $x\in [0,1]^d$, by \eqref{def A^x}. Applying Fubini's theorem gives
\begin{eqnarray*}
 \ensuremath{\mathbb{E}} \lambda (\ensuremath{D_{\text{fat}}^{d}}) &=& \int_{\Omega}\int_{[0,1]^{d}} 1_{\ensuremath{D_{\text{fat}}^{d}}}(x,\omega)d\lambda d\ensuremath{\mathbb{P}} \\
&=&  \int_{[0,1]^{d}}\int_{\Omega} 1_{\ensuremath{D_{\text{fat}}^{d}}}(x,\omega) d\ensuremath{\mathbb{P}} d\lambda\\
&=& \int_{[0,1]^{d}} \ensuremath{\mathbb{P}}(x \in \ensuremath{D_{\text{fat}}^{d}}) d\lambda = 0.
\end{eqnarray*}
 Therefore $\lambda(\ensuremath{D_{\text{fat}}^{d}})=0$ a.s. By Theorem \ref{thm12} we have $\lambda(\ensuremath{D_{\text{fat}}^{c}})> 0$ a.s.\ given non-extinction.

Next suppose that $\lambda(V)=1$. Then with a similar argument we can show that $\lambda(\ensuremath{D_{\text{fat}}^{c}})=0$ and $\lambda(\ensuremath{D_{\text{fat}}^{d}})>0$ a.s.\ given non-extinction.

Proof of Theorem \ref{thm subcritical
}\label{sec subcritical}

Let $p<\ensuremath{p_{c}(d)}$ and consider a sequence $(k(N))_{N \geq 2}$ such that $k(N)/N^{d} \leq p$, for all $N \geq 2$, and $k(N)/N^d \to p$ as $N \to \infty$. Our goal is to show that the probability that the unit cube is crossed by $D_{k(N)}$, is equal to zero for all $N$ large enough. Let $N \geq 2$ and let $D_{p_{0}}$ be the limit set of an MFP process with parameters $p_0$ and $N$, where $p<p_0<\ensuremath{p_{c}(d)}$. First, part (a) of Theorem 2 in \cite{FalGri} states that 
\begin{equation}\label{pc subcritical}
\ensuremath{p_{c}(d)} \leq p_c(N,d),
\end{equation}
 for all $N$. Hence, the MFP process with parameter $p_0<\ensuremath{p_{c}(d)}$ is subcritical. Therefore, a natural approach to prove that the probability that $D_{k(N)}$ crosses the unit cube equals zero for $N$ large enough would be to couple the limit set $D_{k(N)}$ to the limit set $D_{p_{0}}$ in such a way that $D_{k(N)} \subset D_{p_{0}}$. However, a ``direct" coupling between the limit sets $D_{k(N)}$ and $D_{p_{0}}$ is not possible, since with fixed positive probability at each iteration of the MFP process the number of retained subcubes is less than $k(N)$. We therefore need to find a more refined coupling.


The following is an informal strategy of the proof. We will define an event $E$ on which the MFP process contains an infinite tree of retained subcubes, such that each subcube in this tree contains at least $k(N)$ retained subcubes in the tree. Next, we perform a construction of two auxiliary random subsets of the unit cube, from which it will follow that the law of $D_{k(N)}$ is stochastically dominated by the conditional law of $D_{p_0}$, conditioned on the event $E$. In particular, the probability that $D_{k(N)}$ crosses $[0,1]^d$ is less than or equal to the conditional probability that $D_{p_{0}}$ crosses the unit cube, given $E$. The latter probability is zero for $N$ large enough, since the event $E$ has positive probability for $N$ large enough and the MFP process is subcritical.


Let us start by defining the event $E$. Consider an MFP process with parameters $p_0$ and $N$. For notational convenience we call the unit cube the level-0 cube. A level-$n$ cube, $n \geq 0$, is declared \emph{0-good} if it is retained and contains at least $k(N)$ retained level-$(n+1)$ subcubes. (We adopt the convention that $[0,1]^d$ is automatically retained.)
Recursively, we define the notion \emph{$m$-good}, for $m\geq 0$. A level-$n$ cube, for $n\geq 0$, is $(m+1)$-good if it is retained and contains at least $k(N)$ $m$-good subcubes. We say that the unit cube is \emph{$\infty$-good} if it is $m$-good for every $m\geq0$. Define the following events
\begin{eqnarray}
 E_m := \{ [0,1]^d  \text{ is } m\text{-good}\}, \label{E_m} \nonumber \\
 E:= \{[0,1]^d \text{ is } \infty\text{-good}\}. \label{E}
\end{eqnarray}


The following lemma states that we can make the probability of $E$ arbitrary close to 1, for $N$ large enough. In particular, $E$ has positive probability for large enough $N$, which will be sufficient for the proof of Theorem \ref{thm subcritical}.

\begin{lemma}\label{lem high prob}
 Let $p_0 < \ensuremath{p_{c}(d)}$. Let $(k(N))_{N\geq 2}$ be a sequence of integers satisfying $\limsup_{N \to \infty} k(N)/N^d < p_0$. Consider an MFP model with parameters $p_0$ and $N$. For all $\epsilon>0$ there exists $N_0$ such that $\ensuremath{\mathbb{P}}_{p_{0}}(E) > 1-\epsilon$ for all $N \geq N_0$.
\end{lemma}


\begin{proof} Let $\delta>0$ and $N_0$ be such that $k(N)/N^d \leq p_0-2\delta =:p$ for all $N \geq N_0$. Choose $N_1 \geq N_0$ so large that $p_0/(4\delta^2 N^d) < \delta $ for $N \geq N_1$. We will show that
\begin{equation}\label{induction E}
\ensuremath{\mathbb{P}}_{p_{0}}(E_m) \geq 1-\frac{1}{4 \delta^2 N^{d}} ,
\end{equation}
for all $m\geq 0$ and $N\geq N_1$. Since $E_m$ decreases to $E$ as $m\to\infty$, it follows that 
\[
 \ensuremath{\mathbb{P}}_{p_{0}}(E) = \lim_{m \to \infty} \ensuremath{\mathbb{P}}_{p_{0}}(E_m) \geq 1-\frac{1}{4 \delta^2 N^{d}},
\]
for $N \geq N_1$. Now take $N_2\geq N_1$ so large that $1- \frac{1}{4 \delta^2 N^d} > 1- \epsilon$ for all $N \geq N_2$. It remains to show \eqref{induction E}.

We prove \eqref{induction E} by induction on $m$. Consider the event $E_0$, i.e.\ the event that the unit cube contains at least $k(N)$ retained level-1 subcubes. Let $X(n,p)$ denote a binomially distributed random variable with parameters $n\in \ensuremath{\mathbb{N}}$ and $p\in [0,1]$. Since the number of retained level-1 cubes has a binomial distribution with parameters $N^{d}$ and $p_0$, it follows from Chebyshev's inequality that, for every $N \geq N_1$, we have (writing $\ensuremath{\mathbb{P}}$ for the probability measure governing the binomially distributed random variables)
\begin{eqnarray*}
 \ensuremath{\mathbb{P}}_{p_{0}}(E_0) &=& \ensuremath{\mathbb{P}}(X(N^d,p_0) \geq k(N))  \\
 &\geq& \ensuremath{\mathbb{P}}(X(N^d,p_0) \geq p N^d) \\
&\geq&  1- \frac{\ensuremath{\IV\text{ar}} X(N^d,p_0)}{4\delta^2 N^{2d}} \\
&=& 1 -\frac{p_0(1-p_0)N^d}{4 \delta^2 N^{2d}} \\
&\geq& 1- \frac{1}{4 \delta^2 N^{d}}.
\end{eqnarray*}

Next, let $m\geq 0$ and $N \geq N_1$ and suppose that \eqref{induction E} holds for this $m$ and $N$. Recall that $E_{m+1}$ is the event that the unit cube contains at least $k(N)$ $m$-good level-1 cubes. The probability that a level-1 cube is $m$-good, given that it is retained, is equal to $\ensuremath{\mathbb{P}}_{p_0}(E_m)$. Using the induction hypothesis, we get
\begin{eqnarray*}
 \ensuremath{\mathbb{P}}_{p_{0}}(E_{m+1}) &=& \ensuremath{\mathbb{P}}(X(N^{d},p_{0}\ensuremath{\mathbb{P}}_{p_{0}}(E_m)) \geq k(N)) \\
& \geq& \ensuremath{\mathbb{P}}(X(N^d,p_0(1-\textstyle{\frac{1}{4 \delta^2 N^{d}}})) \geq k(N)). 
\end{eqnarray*}
By our choices for $\delta$ and $N$ it follows that $p_0(1-\frac{1}{4 \delta^2 N^{d}}) > p+\delta$. Hence, using Chebyshev's inequality, we get
\begin{eqnarray*}
\ensuremath{\mathbb{P}}(X(N^d,p_0(1-\textstyle{\frac{1}{4 \delta^2 N^{d}}})) \geq k(N))
&\geq&\ensuremath{\mathbb{P}}(X(N^d, p+\delta) \geq k(N)) \\
&\geq& \ensuremath{\mathbb{P}}(X(N^d, p+ \delta) \geq pN^d) \\
&\geq& 1- \frac{\ensuremath{\IV\text{ar}} X(N^d,p+\delta)}{\delta^2 N^{2d}} \\
 &\geq& 1-  \frac{1}{4\delta^2N^{d}}.
\end{eqnarray*}
Therefore, the induction step is valid and we have proved \eqref{induction E}.
\end{proof}



\begin{proof}[Proof of Theorem \ref{thm subcritical}]
Let $p,p_0$ be such that $p < p_0 < \ensuremath{p_{c}(d)}$. Let $(k(N))_{N \geq 2}$ be a sequence such that $k(N)/N^d \leq p$, for all $N \geq 2$, and $k(N)/N^d \to p$ as $N \to \infty$. Consider an MFP model with parameters $p_0$ and $N$ and define the event $E$ as in \eqref{E}. Henceforth, we assume that $N$ is so large that $\ensuremath{\mathbb{P}}_{p_0}(E)>0$, which is possible by Lemma \ref{lem high prob}. In order to prove Theorem \ref{thm subcritical} we will use $E$ to construct two random subsets, $\tilde{D}_{p_{0}}$ and $\tilde{D}_{k(N)}$, of the unit cube, on a common probability space and with the following properties: 
\begin{itemize}
 \item[(i)] $\tilde{D}_{k(N)} \subset \tilde{D}_{p_{0}}$;
\item[(ii)] the law of $\tilde{D}_{p_{0}}$ is stochastically dominated by the conditional law of $D_{p_{0}}$, conditioned on the event $E$;
\item[(iii)] the law of $\tilde D_{k(N)}$ is the same as the law of $D_{k(N)}$.
\end{itemize}


It follows that the law of $D_{k(N)}$ is stochastically dominated by the conditional law of $D_{p_0}$, 
conditioned on the event $E$. Hence, the probability that the unit cube is crossed by $D_{k(N)}$ is at most the conditional probability that $D_{p_0}$ crosses the unit cube, conditioned on the event $E$. By \eqref{pc subcritical} the MFP process with parameter $p_0$ is subcritical, thus the latter probability equals zero. Using the fact that $k(N)/N^d \to p$ as $N \to \infty$, we conclude that
\[
 \liminf_{N \to \infty} \frac{k_{c}(N,d)}{N^{d}} \geq p.
\]
Since $p<\ensuremath{p_{c}(d)}$ was arbitrary, we get
\[
 \liminf_{N \to \infty} \frac{k_{c}(N,d)}{N^{d}} \geq \ensuremath{p_{c}(d)}.
\]


It remains to construct random sets $\tilde{D}_{p_{0}},\tilde{D}_{k(N)}$ with the properties (i)-(iii). First we construct two sequences $(\tilde{D}_{p_{0}}^n)_{n\geq 1}, (\tilde{D}_{k(N)}^n)_{n\geq 1}$ of decreasing random subsets.
Let ${\cal L}$ be the conditional law of the number of $\infty$-good level-1 cubes of the MFP process, conditioned on the event $E$. Note that the support of ${\cal L}$ is $\{k(N),k(N)+1,\ldots,N^d\}$. Furthermore, for a fixed level-$n$ cube $C(\ensuremath{\mathbf{I}})$, ${\cal L}$ is also equal to the conditional law of the number of $\infty$-good level-$(n+1)$ subcubes in $C(\ensuremath{\mathbf{I}})$, conditioned on $C(\ensuremath{\mathbf{I}})$ being $\infty$-good. 

Choose an integer $l$ according to ${\cal L}$ and choose $l$ level-1 cubes uniformly. Define $\tilde D_{p_0}^1$ as the closure of the union of these $l$ level-1 cubes. Choose $k(N)$ out of these $l$ cubes in a uniform way and define $\tilde D_{k(N)}^1$ as the closure of the union of these $k(N)$ cubes.  For each level-1 cube $C({\bf I}) \subset \tilde D_{p_0}^1$, pick an integer $l({\bf I})$ according to ${\cal L}$, independently of other cubes, and choose $l({\bf I})$ level-2 subcubes of $C({\bf I})$ in a uniform way. Define $\tilde D_{p_0}^2$ as the closure of the union of all selected level-2 cubes. For each level-1 cube $C({\bf I}) \subset \tilde D_{k(N)}^1$, uniformly choose $k(N)$ out of the $l({\bf I})$ selected level-2 subcubes. Define $\tilde D_{k(N)}^2$ as the closure of the union of the $k(N)^2$ selected level-2 cubes of $C(\ensuremath{\mathbf{I}})$. Iterating this procedure yields two infinite decreasing sequences of random subsets $(\tilde{D}_{p_{0}}^n)_{n\geq 1}, (\tilde{D}_{k(N)}^n)_{n\geq 1}$.


Now define 
\[
 \tilde D_{p_0} := \bigcap_{n=1}^{\infty} \tilde D_{p_0}^n,\quad \tilde D_{k(N)} := \bigcap_{n=1}^{\infty} \tilde D_{k(N)}^n.
\]
By construction, for each $n\geq 1$, we have that (1) $\tilde D_{k(N)}^n \subset \tilde D_{p_0}^n$, (2) the law of $\tilde{D}_{p_{0}}^n$ is stochastically dominated by the conditional law of $D_{p_{0}}^n$ given $E$ and (3) the law of $\tilde D_{k(N)}^n$ is equal to the law of $D_{k(N)}^n$. It follows that the limit sets $\tilde{D}_{p_{0}},\tilde{D}_{k(N)}$ satisfy properties (i)-(iii).
\end{proof}

Proof of Theorem \ref{thm supercritical
}\label{sec supercritical}

Let us start by outlining the proof. The first part consists mainly of setting up the framework, where we use the notation of Falconer and Grimmett \cite{FalGri}, which will enable us in the second part to prove that the subcubes of the fractal process satisfy certain ``good'' properties with probability arbitrarily close to 1 as $N\to \infty$. Informally, a subcube is good when there exist many connections inside the cube between its faces and when it is also connected to other good subcubes. Therefore, the probability of crossing the unit cube converges to 1 as $N\to\infty$.

Although we will partly follow \cite{FalGri}, it does not seem possible to use Theorem 2.2 of \cite{FalGri} directly. 
First, we state (a slightly adapted version of) Lemma 2 of \cite{FalGri}, which concerns site percolation with parameter $\pi$ on $\ensuremath{\mathbb{L}}^d$. We let every vertex of $\ensuremath{\mathbb{L}}^d$ be colored \emph{black} with probability $\pi$ and \emph{white} otherwise, independently of other vertices. We write $P_\pi$ for the ensuing product measure with density $\pi \in [0,1]$. We call a subset $C$ of $\ensuremath{\mathbb{L}}^{d}$ a \emph{black cluster} if it is a maximal connected subset (with respect to the adjacency relation on $\ensuremath{\mathbb{L}}^d$) of black vertices. Denote the cube with vertex set  $\{1,2,\ldots,N\}^d$ by $B_N$. Let $\ensuremath{\mathcal{L}}$ be the set of edges of the unit cube $[0,1]^d$, that is $\ensuremath{\mathcal{L}}$ contains all sets of the form
\[
 L_{r}(\mathbf{a})=\{a_1\} \times \{a_2\} \times \cdots \times \{a_{r-1}\} \times [0,1] \times \{a_{r+1}\} \times \cdots \times \{a_d\}
\]
as $r$ ranges over $\{1,\ldots,d\}$ and $\mathbf{a} = (a_1,a_2,\ldots,a_d)$ ranges over $\{0,1\}^d$. For each $L=L_{r}(\mathbf{a}) \in \ensuremath{\mathcal{L}}$ we write 
\[
L_N=\{ \mathbf{x} \in B_N: x_{i} = \max\{1,a_{i}N\} \text{ for } 1 \leq i \leq d, i \neq r \}
\]
for the corresponding edge of $B_N$.


\begin{lemma}\label{lem FalGri}
 Suppose $\pi>\ensuremath{p_{c}(d)}, \epsilon>0$ and let $q$ be a positive integer. There exist positive integers $u$ and $N_1$ such that the following holds for all $N \geq N_1$. Let $U(1),\ldots,U(q)$ be subsets of vertices of $B_N$ such that for each $r\in\{1,\ldots,q\}$, (i) $|U(r)| \geq u$ and (ii) there exists $L \in \ensuremath{\mathcal{L}}$ such that $U(r) \subset L_N$. Then, 
\begin{equation}\label{perc bound}
 P_{\pi}\left(\begin{array}{c}
      \text{there exists a black cluster } C_N \text{ such that }|C_N \cap L_N| \geq u \\
      \text{ for all } L \in \ensuremath{\mathcal{L}}, \text{ and } | C_N \cap U(r)| \geq 1, \text{ for all } r\in\{1,\ldots,q\} \end{array}\right) \geq 1- \frac{\epsilon}{2}.
\end{equation}
\end{lemma}


Our goal is to show that the following holds uniformly in $n$: With probability arbitrarily close to 1 as $N \to \infty$, there is a sequence of cubes in $D_{k(N)}^n$, each with at least one edge in common with the next, which crosses the unit cube. In order to prove this we examine the cubes $C(\ensuremath{\mathbf{I}})$, for $\ensuremath{\mathbf{I}}\in\ensuremath{\mathcal{J}}^{(n)}$, in turn according to the ordering on $\ensuremath{\mathcal{J}}^{(n)}$, and declare some of them to be good according to the rule given below. Since the probabilistic bounds on the goodness of cubes will hold uniformly in $n$, the desired conclusion follows. 


Fix integers $n,u,k \geq 1$ until Lemma \ref{lem prob}. For $m\geq 1$, identify a level-$m$ cube with a vertex in $B_{N^m} \subset \ensuremath{\mathbb{L}}^d$ in the canonical way. A set of level-$m$ cubes $\{C(\ensuremath{\mathbf{I}}_1),\ldots,C(\ensuremath{\mathbf{I}}_l)\}$ is called \emph{edge-connected} if they form a connected set with respect to the adjacency relation of $\ensuremath{\mathbb{L}}^d$. Whether a cube $C(\ensuremath{\mathbf{I}})$, for $\ensuremath{\mathbf{I}} \in \ensuremath{\mathcal{J}}^{(n)}$, is called \emph{$(n,u)$-good} or not, is determined by the following inductive procedure. Let $\ensuremath{\mathbf{I}} \in \ensuremath{\mathcal{J}}^{(n)}$, and assume that the goodness of $C(\ensuremath{\mathbf{I}}')$ has been decided for all $\ensuremath{\mathbf{I}}' < \ensuremath{\mathbf{I}}$. We have the following possibilities:
\begin{itemize}
 \item[(a)] $|\ensuremath{\mathbf{I}}|=n$. Then $C(\ensuremath{\mathbf{I}})$ is always declared $(n,u)$-good.
\item[(b)] $0 \leq |\ensuremath{\mathbf{I}}| = m<n$.
\end{itemize}
In the latter case we act as follows. Note that the subcubes $C(\ensuremath{\mathbf{I}},\mathbf{j})$ with $\ensuremath{\mathbf{j}} \in J^d$ have already been examined, since $(\ensuremath{\mathbf{I}},\ensuremath{\mathbf{j}}) < \ensuremath{\mathbf{I}}$.
Define the following set of level-$(m+1)$ subcubes of $C(\ensuremath{\mathbf{I}})$, 
\begin{equation}\label{good subcubes}
   \ensuremath{\mathcal{D}}(\ensuremath{\mathbf{I}}):= \{ C(\ensuremath{\mathbf{I}},\ensuremath{\mathbf{j}}): \ensuremath{\mathbf{j}} \in J^d \text{ with } C(\ensuremath{\mathbf{I}},\ensuremath{\mathbf{j}}) \, (n,u)\text{-good and } Z_k(\ensuremath{\mathbf{I}},\ensuremath{\mathbf{j}}) =1 \}. 
 \end{equation}
We declare $C(\ensuremath{\mathbf{I}})$ to be $(n,u)$-good if there exists an edge-connected set $\ensuremath{\mathcal{H}}(\ensuremath{\mathbf{I}})\subset \ensuremath{\mathcal{D}}(\ensuremath{\mathbf{I}})$ such that
\begin{itemize}
 \item[(i)] Each edge of $C(\ensuremath{\mathbf{I}})$ intersects at least $u$ cubes of $\ensuremath{\mathcal{H}}(\ensuremath{\mathbf{I}})$;
\item[(ii)] For every $(n,u)$-good level-$m$ cube $C(\ensuremath{\mathbf{I}}')$ with $\ensuremath{\mathbf{I}}'<\ensuremath{\mathbf{I}}$ that has (at least) one edge in common with $C(\ensuremath{\mathbf{I}})$, there are a cube of $\ensuremath{\mathcal{H}}(\ensuremath{\mathbf{I}}')$ and a cube of $\ensuremath{\mathcal{H}}(\ensuremath{\mathbf{I}})$ with a common edge.
\end{itemize}
(If there is more than one candidate for $\ensuremath{\mathcal{H}}(\ensuremath{\mathbf{I}})$ we use some deterministic rule to choose one of them.)
This procedure determines whether $C(\ensuremath{\mathbf{I}})$ is $(n,u)$-good for each $\ensuremath{\mathbf{I}}$ in turn. Note that it is easier for higher level cubes to be $(n,u)$-good than for lower level cubes. In particular, for the unit cube, i.e.\ $C(\emptyset)$, it is the hardest to be $(n,u)$-good. 


The next lemma shows that if the unit cube is $(n,u)$-good then there is a sequence of cubes in $D_k^n$, each with at least one edge in common with the next, which connects the ``left-hand side'' of $[0,1]^d$ with its ``right-hand side''. If such a sequence of cubes exists in $D_k^n$ we say that \emph{percolation occurs in $D_{k}^{n}$}. 


\begin{lemma}\label{lem good}
 Suppose $[0,1]^d$ is $(n,u)$-good, then percolation occurs in $D_{k}^{n}$.
\end{lemma}

\begin{proof}
Assume that the unit cube, i.e.\ $C(\emptyset)$, is $(n,u)$-good. We will show, with a recursive argument, that for $1\leq m \leq n$ there exists an edge-connected chain of retained $(n,u)$-good level-$m$ cubes which joins $\{0\} \times [0,1]^{d-1}$ and $\{1\} \times [0,1]^{d-1}$. In particular, this holds for $m=n$ and hence percolation occurs in $D_k^n$.


Since the unit cube is assumed to be $(n,u)$-good, $\ensuremath{\mathcal{D}}(\emptyset)$ contains by definition an edge-connected subset $\ensuremath{\mathcal{H}}(\emptyset)$ of retained $(n,u)$-good level-1 subcubes, such that each edge of $C(\emptyset)$ intersects at least $u$ cubes of $\ensuremath{\mathcal{H}}(\emptyset)$. In particular, there is a sequence of retained $(n,u)$-good edge-connected level-1 cubes that connects the left-hand side of $[0,1]^d$ with its right-hand side.


Let $1\leq m < n$ and assume that there exists an edge-connected chain $C(\ensuremath{\mathbf{I}}_1),\ldots,C(\ensuremath{\mathbf{I}}_l)$ of retained $(n,u)$-good level-$m$ cubes which connects the left-hand side of $[0,1]^d$ with its right-hand side. For each $i$, $1 \leq i \leq l$, either $\ensuremath{\mathbf{I}}_i < \ensuremath{\mathbf{I}}_{i+1}$ or $\ensuremath{\mathbf{I}}_{i+1}<\ensuremath{\mathbf{I}}_i$. By condition (ii), there exist level-$(m+1)$ cubes of $\ensuremath{\mathcal{H}}(\ensuremath{\mathbf{I}}_{i+1})$ which are edge-connected to level-$(m+1)$ cubes of $\ensuremath{\mathcal{H}}(\ensuremath{\mathbf{I}}_i)$. These level-$(m+1)$ cubes $C(\ensuremath{\mathbf{J}})$ are all $(n,u)$-good and have $Z_k(\ensuremath{\mathbf{J}})=1$, by \eqref{good subcubes} and the definition of the $\ensuremath{\mathcal{H}}(\ensuremath{\mathbf{I}})$. It follows that there is an edge-connected chain of retained $(n,u)$-good level-$(m+1)$ cubes $C(\ensuremath{\mathbf{J}})$ which joins $\{0\} \times [0,1]^{d-1}$ and $\{1\} \times [0,1]^{d-1}$. 
\end{proof}


For $\ensuremath{\mathbf{I}} \in \ensuremath{\mathcal{J}}^{(n)}$, define the index $\ensuremath{\mathbf{I}}^- \in \ensuremath{\mathcal{J}}^{(n)}$ by
\[
 \ensuremath{\mathbf{I}}^- = \max\{ \ensuremath{\mathbf{I}}': \ensuremath{\mathbf{I}}' < \ensuremath{\mathbf{I}} \text{ and } |\ensuremath{\mathbf{I}}'| \leq |\ensuremath{\mathbf{I}}| \}.
\]
If there is no such index, $\ensuremath{\mathbf{I}}^-$ is left undefined. For each $\ensuremath{\mathbf{I}} \in \ensuremath{\mathcal{J}}^{(n)}$ we let $\ensuremath{\mathcal{F}}(\ensuremath{\mathbf{I}})$ denote the $\sigma$-field 
\[
 \ensuremath{\mathcal{F}}(\ensuremath{\mathbf{I}}) = \sigma(Z_k(\ensuremath{\mathbf{I}}',\ensuremath{\mathbf{j}}): |\ensuremath{\mathbf{I}}'| \leq n-1, \ensuremath{\mathbf{I}}' \leq \ensuremath{\mathbf{I}}, \ensuremath{\mathbf{j}} \in J^{d}).
\]
If $\ensuremath{\mathbf{I}}^-$ is undefined, we take $\ensuremath{\mathcal{F}}(\ensuremath{\mathbf{I}}^-)$ to be the trivial $\sigma$-field. Note that $\ensuremath{\mathcal{F}}(\ensuremath{\mathbf{I}})$ is generated by those $Z_k$ that have been examined prior to deciding whether $C(\ensuremath{\mathbf{I}})$ is $(n,u)$-good. In particular, by virtue of the ordering on the cubes as introduced in Section \ref{sec pre}, $\ensuremath{\mathcal{F}}(\ensuremath{\mathbf{I}}^-)$ does \emph{not} contain any information about subcubes of $\ensuremath{\mathbf{I}}$. 


Let $p>\ensuremath{p_{c}(d)}$ and let $(k(N))_{N \geq 2}$ be a sequence such that $k(N)/N^d \geq p$, for all $N \geq 2$. We want to prove that, for every $\epsilon>0$, the probability that $[0,1]^d$ is $(n,u)$-good in the $k(N)$-model is at least $1-\epsilon$, 
for $N \geq N_0$, where $N_0$ is an integer which has to be taken sufficiently large to satisfy certain probabilistic bounds but is independent of $n$.


Let us first give a sketch of the proof. Fix $N\geq N_0$ and consider the $k(N)$-model. We use a recursive argument. The smallest level-$n$ cube according to the ordering on $\ensuremath{\mathcal{J}}^{(n)}$ is by definition $(n,u)$-good. Let $\ensuremath{\mathbf{I}} \in \ensuremath{\mathcal{J}}^{(n)}$ and assume that $\ensuremath{\mathbb{P}}_{k(N)}(C(\ensuremath{\mathbf{I}}') \text{ is } (n,u)\text{-good} \mid \ensuremath{\mathcal{F}}(\ensuremath{\mathbf{I}}'^-)) \geq 1-\epsilon$ for all $\ensuremath{\mathbf{I}}'<\ensuremath{\mathbf{I}}$. We prove that, given $\ensuremath{\mathcal{F}}(\ensuremath{\mathbf{I}}^-)$, $C(\ensuremath{\mathbf{I}})$ is $(n,u)$-good with probability at least $1-\epsilon$. The proof of this consists of a coupling between a product measure with density $\pi \in (\ensuremath{p_{c}(d)},(1-\epsilon)p)$ in the box $B_N$ and the law of the set of subcubes $C(\ensuremath{\mathbf{I}},\ensuremath{\mathbf{j}})$ of $C(\ensuremath{\mathbf{I}})$ which are $(n,u)$-good and satisfy $Z_{k(N)}(\ensuremath{\mathbf{I}},\ensuremath{\mathbf{j}}) = 1$. Applying Lemma \ref{lem FalGri} to the product measure combined with the coupling yields that the subcubes satisfy properties (i) and (ii) with probability at least $1-\epsilon$. Therefore, given $\ensuremath{\mathcal{F}}(\ensuremath{\mathbf{I}}^-)$, $C(\ensuremath{\mathbf{I}})$ is $(n,u)$-good with probability at least $1-\epsilon$. Iterating this argument then yields that the unit cube is $(n,u)$-good with probability at least $1-\epsilon$, for $N \geq N_0$.


The proof in \cite{FalGri} of the analogous result that $\sigma(p,N,d) \to 1$ as $N \to \infty$ for $p> \ensuremath{p_{c}(d)}$ is considerably less involved. In the context of \cite{FalGri}, subcubes are retained with probability $p$ independently of other cubes, which is not the case in $k$-fractal percolation. Therefore, they can directly show that there exists $\pi>\ensuremath{p_{c}(d)}$ such that, for $\ensuremath{\mathbf{I}} \in \ensuremath{\mathcal{J}}^{(n)}$, the law of the set of subcubes $C(\ensuremath{\mathbf{I}},\ensuremath{\mathbf{j}})$ of $C(\ensuremath{\mathbf{I}})$ which are good and satisfy $Z_p(\ensuremath{\mathbf{I}},\ensuremath{\mathbf{j}}) = 1$, dominates an i.i.d.\ process on the box $B_N$ with density $\pi$.


We need the following result for binomially distributed random variables, which we state as a lemma for future reference. Since the result follows easily from Chebyshev's inequality, we omit the proof.


\begin{lemma}\label{lem good3}
Let $p > \ensuremath{p_{c}(d)}$ and let $(k(N))_{N \geq 2}$ be a sequence of integers such that $k(N)/N^d \geq p$ for all  $N \geq 2$. Let $\epsilon>0$ be such that $(1-\epsilon) p > \ensuremath{p_{c}(d)}$, let $\pi \in (\ensuremath{p_{c}(d)}, (1-\epsilon) p)$ and define $M:= ((1-\epsilon)p+\pi)N^d / 2$. There exists $N_2$ such that 
\[
\ensuremath{\mathbb{P}}(\{X(k(N),1-\epsilon) \geq M\} \cap \{X'(N^{d},\pi) \leq M\}) \geq 1-\epsilon/2,
\]
for $N \geq N_2$, where $X$ and $X'$ are independent, binomially distributed random variables with the indicated parameters.
\end{lemma}


We now prove that, for any $\epsilon>0$, the unit cube is $(n,u)$-good with probability at least $1-\epsilon$, for $N$ large enough but independent of $n$.


\begin{lemma} \label{lem prob}
Let $p> \ensuremath{p_{c}(d)}$ and let $(k(N))_{N \geq 2}$ be a sequence of integers such that $k(N)/N^{d} \geq  p$, for all $N \geq 2$. Let $\epsilon>0$ be such that $(1-\epsilon)p>\ensuremath{p_{c}(d)}$. Take $\pi \in (\ensuremath{p_{c}(d)}, (1-\epsilon)p)$ and set $q=3^d$. Let $u$ and $N_1$ be given by Lemma \ref{lem FalGri}. Let $N_2$ be given by Lemma \ref{lem good3}.  Set $N_0 =\max\{N_1,N_2\}$. Then, for all $n \geq 1$,
\begin{equation}\label{unit cube good}
 \ensuremath{\mathbb{P}}_{k(N)}([0,1]^d \text{ is } (n,u)\text{-good}) \geq 1-\epsilon,
\end{equation}
for all $N \geq N_0$.
\end{lemma}


\begin{proof}
Fix $N \geq N_0$ and $n\geq 1$ and consider the $k(N)$-fractal model. Our aim is to show that 
\begin{equation}\label{induction2}
 \ensuremath{\mathbb{P}}_{k(N)}(C(\ensuremath{\mathbf{I}}) \text{ is } (n,u)\text{-good} \mid \ensuremath{\mathcal{F}}(\ensuremath{\mathbf{I}}^-)) \geq 1 -\epsilon
\end{equation}
holds for all $\ensuremath{\mathbf{I}} \in \ensuremath{\mathcal{J}}^{(n)}$. Taking $\ensuremath{\mathbf{I}}=\emptyset$ then yields \eqref{unit cube good}. We prove this with a recursive argument. Let $\ensuremath{\mathbf{I}}_0$ be the smallest index in $\ensuremath{\mathcal{J}}^{(n)}$, according to the ordering on $\ensuremath{\mathcal{J}}^{(n)}$. By virtue of the ordering, we have $|\ensuremath{\mathbf{I}}_0| = n$. Hence, by definition, $C(\ensuremath{\mathbf{I}}_0)$ is $(n,u)$-good. In particular, \eqref{induction2} holds for $\ensuremath{\mathbf{I}}_0$.


The recursive step is as follows. Take an index $\ensuremath{\mathbf{I}} \in \ensuremath{\mathcal{J}}^{(n)}$ and assume that  
\begin{equation}\label{induction}
 \ensuremath{\mathbb{P}}_{k(N)}(C(\ensuremath{\mathbf{I}}') \text{ is } (n,u)\text{-good} \mid \ensuremath{\mathcal{F}}(\ensuremath{\mathbf{I}}'^-)) \geq 1 -\epsilon,
\end{equation}
has been established for all indices $\ensuremath{\mathbf{I}}'$ in $\ensuremath{\mathcal{J}}^{(n)}$ less than $\ensuremath{\mathbf{I}}$. We have to show that \eqref{induction2} holds for $\ensuremath{\mathbf{I}}$ given this assumption. We have two cases:
\begin{itemize}
 \item[(a)] $|\ensuremath{\mathbf{I}}| =n$; then $\ensuremath{\mathbb{P}}_{k(N)}(C(\ensuremath{\mathbf{I}}) \text{ is } (n,u)\text{-good}) =1$ and \eqref{induction2} is true.
\item[(b)] $0 \leq |\ensuremath{\mathbf{I}}| = m < n$.
\end{itemize}


For case (b), given $\ensuremath{\mathcal{F}}(\ensuremath{\mathbf{I}}^-)$, the goodness of $C(\ensuremath{\mathbf{I}}')$ is determined (in particular) for all $\ensuremath{\mathbf{I}}' < \ensuremath{\mathbf{I}}$ with $|\ensuremath{\mathbf{I}}|=m$. Let
\begin{eqnarray*}
 \ensuremath{\mathcal{Q}}=\left\{\begin{array}{cc} \ensuremath{\mathbf{I}}': & \ensuremath{\mathbf{I}}'<\ensuremath{\mathbf{I}} \text{ and } C(\ensuremath{\mathbf{I}}') \text{ is an } (n,u)\text{-good level-}m \\
& \text{ cube with an edge in common with }C(\ensuremath{\mathbf{I}})           
          \end{array}\right\}.
\end{eqnarray*}
For each $\ensuremath{\mathbf{I}}' \in \ensuremath{\mathcal{Q}}$, let $E(\ensuremath{\mathbf{I}}')$ be some common edge of $C(\ensuremath{\mathbf{I}})$ and $C(\ensuremath{\mathbf{I}}')$. Since $C(\ensuremath{\mathbf{I}}')$ is $(n,u)$-good, there are at least $u$ level-$(m+1)$ subcubes in $\ensuremath{\mathcal{H}}(\ensuremath{\mathbf{I}}')$ which intersect $E(\ensuremath{\mathbf{I}}')$; call this set of subcubes $\ensuremath{\mathcal{U}}(\ensuremath{\mathbf{I}}')$. To see whether $C(\ensuremath{\mathbf{I}})$ is $(n,u)$-good, we look at $C(\ensuremath{\mathbf{I}},\ensuremath{\mathbf{j}}(l))$ where $\ensuremath{\mathbf{j}}(l), 1 \leq l \leq N^d,$ are the vectors of $J^d$ arranged in order. We have $(\ensuremath{\mathbf{I}},\ensuremath{\mathbf{j}}(l)) < \ensuremath{\mathbf{I}}$, so by the induction hypothesis \eqref{induction} we have
\begin{equation}\label{induction sub}
 \ensuremath{\mathbb{P}}_{k(N)}(C(\ensuremath{\mathbf{I}},\ensuremath{\mathbf{j}}(l)) \text{ is } (n,u)\text{-good} \mid \ensuremath{\mathcal{F}}((\ensuremath{\mathbf{I}},\ensuremath{\mathbf{j}}(l))^-)) \geq 1-\epsilon,
\end{equation}
for all $l$. Note that $\ensuremath{\mathcal{F}}((\ensuremath{\mathbf{I}},\ensuremath{\mathbf{j}}(1))^-) = \ensuremath{\mathcal{F}}(\ensuremath{\mathbf{I}}^-)$.


We identify each subcube of $C(\ensuremath{\mathbf{I}})$ in the canonical way with a vertex in $B_N$. We will construct three random subsets $G_1, G_2, G_3$ of $B_N$ on a common probability space with the following properties:
\begin{itemize}
\item[(I)] the law of $G_1$ equals the law of the set of subcubes $C(\ensuremath{\mathbf{I}},\ensuremath{\mathbf{j}})$ of $C(\ensuremath{\mathbf{I}})$ which are $(n,u)$-good and satisfy $Z_{k(N)}(\ensuremath{\mathbf{I}},\ensuremath{\mathbf{j}})=1$;
\item[(II)] $G_2$ is obtained by first selecting $k(N)$ vertices of $B_N$ uniformly and then retaining each selected vertex with probability $1-\epsilon$, independently of other vertices;
\item[(III)] the law of $G_3$ is the Bernoulli product measure with density $\pi$ on $B_N$;
\item[(IV)] $G_1 \supset G_2$;
\item[(V)] $\ensuremath{\mathbb{P}}(G_2 \supset G_3) \geq 1-\epsilon/2$.
\end{itemize}


From \eqref{induction sub} and a standard coupling technique, sometimes referred to as sequential coupling (see e.g.\ \cite{LigSte}), the construction of $G_1$ and $G_2$ with properties (I), (II) and (IV) is straightforward. The construction of $G_3$ such that properties (III) and (V) hold is given below. Let $|G_2|$ denote the cardinality of the set $G_2$. Define $M=((1-\epsilon)p+\pi)N^d / 2$ and let $R$ be a number drawn from a binomial distribution with parameters $N^d$ and $\pi$, independently of $G_1$ and $G_2$. If $|G_2| \geq M$ and $M\geq R$ we select $R$ vertices uniformly  out of the $|G_2|$ retained vertices of $G_2$ and call this set $G_3$. Otherwise, we select, independently of $G_1$ and $G_2$, $R$ vertices of $B_N$ in a uniform way and call this set $G_3$. From the construction (note that also $G_2$ was obtained in a uniform way) it is clear that $G_3$ satisfies property (III). Observe that $|G_2|$ has a binomial distribution with parameters $k(N)$ and $1-\epsilon$. From Lemma \ref{lem good3} it follows that
\[
 \ensuremath{\mathbb{P}}(\{|G_2| \geq M \} \cap \{R \leq M\}) \geq 1-\epsilon/2.
\]
Hence, property (V) also holds.


Let us now return to the goodness of $C(\ensuremath{\mathbf{I}})$. As before, we identify the random subsets $G_1,G_2,G_3$ of $B_N$ with
the corresponding sets of subcubes  of $C(\ensuremath{\mathbf{I}})$ in the canonical way. It then follows from property (III) and Lemma \ref{lem FalGri} (note that $\ensuremath{\mathcal{Q}}$ has cardinality at most $3^d =q$) that $G_3$ has an edge-connected subset which satisfies the following properties with probability at least $1-\epsilon/2$:
\begin{itemize}
  \item[(i)] intersects every edge of $C(\ensuremath{\mathbf{I}})$ with at least $u$ cubes;
 \item[(ii)] contains a cube that is edge-connected to a cube of $\ensuremath{\mathcal{U}}(\ensuremath{\mathbf{I}}')$, for all $\ensuremath{\mathbf{I}}' \in \ensuremath{\mathcal{Q}}$. 
 \end{itemize}


Combining properties (IV), (V) and the previous paragraph we obtain
\begin{eqnarray*}
 \lefteqn{\ensuremath{\mathbb{P}}_{k(N)}(C(\ensuremath{\mathbf{I}}) \text{ is } (n,u)\text{-good} \mid \ensuremath{\mathcal{F}}(\ensuremath{\mathbf{I}}^-))} \\
& \geq& \ensuremath{\mathbb{P}}(\{G_1 \supset G_3 \} \cap \{G_3 \text{ satisfies properties (i) and (ii)}\}) \\
&\geq& 1-\epsilon.
\end{eqnarray*}
Therefore, \eqref{induction2} holds for the index $\ensuremath{\mathbf{I}}$ given that \eqref{induction} holds for all indices $\ensuremath{\mathbf{I}}'<\ensuremath{\mathbf{I}}$. A recursive use of this argument -- recall that \eqref{induction2} is valid for $\ensuremath{\mathbf{I}}_0$ (the smallest index according to the ordering) -- yields that \eqref{induction2} holds for all $\ensuremath{\mathbf{I}}$. Taking $\ensuremath{\mathbf{I}}=\emptyset$ in \eqref{induction2} proves the lemma.
\end{proof}


We are now able to conclude the proof of Theorem \ref{thm supercritical}.


\begin{proof}[Proof of Theorem \ref{thm supercritical}]
Let $p>\ensuremath{p_{c}(d)}$ and consider a sequence $(k(N))_{N \geq 2}$ such that $k(N)/N^d \geq p$, for all $N \geq 2$. We get, using both Lemma \ref{lem prob} and Lemma \ref{lem good}, that for any $\epsilon >0$ such that $(1-\epsilon)p > \ensuremath{p_{c}(d)}$, there exists $N_0$, depending on $\epsilon$, such that
\begin{equation}\label{level percolation}
 \ensuremath{\mathbb{P}}_{k(N)}(\text{percolation in } D^n_{k(N)}) \geq \ensuremath{\mathbb{P}}_{k(N)}([0,1]^d \text{ is } (n,u)\text{-good}) \geq 1-\epsilon,
\end{equation}
for $N \geq N_0$. It is well known (see e.g.\ \cite{FalGri}) that
\[
 \{[0,1]^d \text{ is crossed by } D_{k(N)} \} = \bigcap_{n=1}^{\infty} \{\text{percolation in } D^n_{k(N)}\}. 
\]
Hence, taking the limit $n\to \infty$ in \eqref{level percolation} yields that for $\epsilon > 0$ small enough
\begin{equation}\label{final percolation}
 \ensuremath{\mathbb{P}}_{k(N)}([0,1]^d \text{ is crossed by } D_{k(N)}) \geq 1-\epsilon,
\end{equation}
for $N \geq N_0$. Therefore, 
\[
 \theta(k(N),N,d) \to 1,
\]
as $N\to \infty$.
\end{proof}

Proof of Theorem \ref{thm lebesgue
}

We start with a heuristic strategy for the proof. For a fixed configuration $\omega \in \Omega$, let us call a point $x$ in the unit cube \emph{conditionally connected} if the following property holds: If we change $\omega$ by retaining all cubes that contain $x$, then $x$ is contained in a connected component larger than one point. We show that for almost all points $x$ it is the case that $x$ is conditionally connected with probability 0 or 1. We define an ergodic transformation $T$ on the unit cube. The transformation $T$ enables us to prove that the probability for a point $x$ to be conditionally connected has the same value for $\lambda$-almost all $x$.  From this we can then conclude that either the set of dust points or the set of connected components contains all Lebesgue measure.


\begin{proof}[Proof of Theorem \ref{thm lebesgue}]
First, we have to introduce some notation. Let $U$ be the collection of points in $[0,1]^d$ not on the boundary of a subcube. For each $x\in U$ there exists a unique sequence $(C({\bf x}_1,\ldots,{\bf x}_n))_{n\geq 1}$ of cubes of the fractal process, where ${\bf x}_j\in J^d$ for all $j$, such that $\bigcap_{n\geq 1} C({\bf x}_1,\ldots,{\bf x}_n) = \{ x \}$. Therefore, we can define an invertible transformation $\phi : U \to (J^d)^{\ensuremath{\mathbb{N}}}$ by $\phi(x) = ({\bf x}_1,{\bf x}_2,\ldots)$. For each $n \in \ensuremath{\mathbb{N}}$ let $\mu_n$ be the uniform measure on $(X_n,\ensuremath{\mathcal{F}}_n)$, where $X_n= J^d$ and $\ensuremath{\mathcal{F}}_n$ is the power set of $X_n$. Let $(X,\ensuremath{\mathcal{F}},\mu)=\bigotimes_{n=1}^{\infty}(X_n,\ensuremath{\mathcal{F}}_n,\mu_n)$ be the product space. Since $\phi : (U,\ensuremath{\mathcal{B}}(U),\lambda) \to (X,\ensuremath{\mathcal{F}},\mu)$ is an invertible measure-preserving transformation, we have that $(X,\ensuremath{\mathcal{F}},\mu)$ is by definition isomorphic to $(U,\ensuremath{\mathcal{B}}(U),\lambda)$. Here $\ensuremath{\mathcal{B}}(U)$ denotes the Borel $\sigma$-algebra.

Next, we define the transformation $T:U\to U$, which will play a crucial role in the rest of the proof. Define the auxiliary shift transformation $T^* : X\to X$ by $T^*(({\bf x}_1,{\bf x}_2,{\bf x}_3,\ldots)) = ({\bf x}_2,{\bf x}_3,\ldots)$, for $({\bf x}_1,{\bf x}_2,\ldots)\in X$. The transformation $T^*$ is measure preserving with respect to the measure $\mu$ and also ergodic, see for instance \cite{Wal}. Let $T := \phi^{-1} \circ T^* \circ \phi$ be the induced transformation on $U$ and note that $T$ is isomorphic to $T^*$ and hence also ergodic. Informally, $T$ sends a point $x\in U$ to the point $Tx$, in such a way that the relative position of $Tx$ in the unit cube is the same as the relative position of $x$ in its level-1 cube $C({\bf x}_1)$; see Figure \ref{fig transformation}.

\begin{figure}[!ht]
\begin{center}
\includegraphics[width=6cm]{transformation}
\caption{Illustration of the transformation $T$. Note that the relative position of $x$ in the level-1 cube is the same as the relative position of $Tx$ in the unit cube.}
\label{fig transformation}
\end{center}
\end{figure}

Recall that $\omega \in \Omega$ denotes a particular realization of the fat fractal percolation process.  For $x \in U$, we define the following event.
\[
 A^x := \left\{\omega: \text{if we set } \omega(C(\textbf{x}_1,\ldots,\textbf{x}_n)) = 1 \text{ for all } n \geq 1, \text{ then } C_{\text{fat}}^{x} \neq \{x\} \right\}.
\]
In other words, $A^{x}$ consists of those configurations $\omega$ such that when we change the configuration by retaining all $C(\textbf{x}_1,\ldots,\textbf{x}_n)$, then in this new configuration, $x$ is in the same connected component as some $y \neq x$. Observe that 
\begin{equation}\label{def A^x}
 A^x \cap \{  x\in \ensuremath{D_{\text{fat}}}\} =\{ x \in \ensuremath{D_{\text{fat}}^{c}} \}.
\end{equation}
It is easy to see that $A^{x}$ is a tail event. Hence, by Kolmogorov's 0-1 law we get $\ensuremath{\mathbb{P}}(A^{x}) \in \{0,1\}$ for all $x\in U$.

However, a priori it is not clear that for almost all $x$ in the unit cube $\ensuremath{\mathbb{P}}(A^x)$ has the same value. To this end, define the set $V:=\{x\in U: \ensuremath{\mathbb{P}}(A^{x})=0\}$. We will show that $\lambda(V)\in \{0,1\}$. Recall that the relative position of $Tx$ in the unit cube is the same as the relative position of $x$ in the level-1 cube $C(\mathbf{x}_1)$. It is possible to construct a coupling between the fractal process in the unit cube and the fractal process in $C(\mathbf{x}_1)$, given that $C(\mathbf{x}_1)$ is retained,  with the following property: For every cube $C(\ensuremath{\mathbf{I}})$ in $C(\mathbf{x}_1)$, it is the case that if $TC(\ensuremath{\mathbf{I}})$ is retained in the fractal process in the unit cube, then $C(\ensuremath{\mathbf{I}})$ is also retained in the fractal process in $C(\mathbf{x}_1)$, given that $C(\mathbf{x}_1)$ is retained. It is straightforward that such a coupling exists since the retention probabilities $p_n$ are non-decreasing in $n$. Hence,
\begin{equation}\label{A^Tx ineq}
 \ensuremath{\mathbb{P}}(A^{Tx}) \leq \ensuremath{\mathbb{P}}(A^x | C(\mathbf{x}_1) \text{ is retained}).
\end{equation}
Furthermore, since $A^x$ is a tail event, we have 
\begin{equation}\label{cond eq}
\ensuremath{\mathbb{P}}(A^x)=\ensuremath{\mathbb{P}}(A^x | C(\mathbf{x}_1) \text{ is retained}). 
\end{equation}
It follows from \eqref{A^Tx ineq} and \eqref{cond eq} that $\ensuremath{\mathbb{P}}(A^{Tx}) \leq \ensuremath{\mathbb{P}}(A^x)$ for all $x$. This implies that $V \subset T^{-1} V$. Because $T$ is measure preserving it follows that 
\[
 \lambda(V \Delta T^{-1} V) = \lambda(V \setminus T^{-1}V) + \lambda(T^{-1}V \setminus V) = 0+\lambda(T^{-1}V) - \lambda(V) = 0.
\]
Ergodicity of $T$ now yields that $\lambda(V) \in \{0,1\}$. 


Suppose $\lambda(V)=0$. Then $\ensuremath{\mathbb{P}}(x \in \ensuremath{D_{\text{fat}}^{d}})=\ensuremath{\mathbb{P}}(\{x\in \ensuremath{D_{\text{fat}}}\} \setminus A^x)=0$ for almost all $x\in [0,1]^d$, by \eqref{def A^x}. Applying Fubini's theorem gives
\begin{eqnarray*}
 \ensuremath{\mathbb{E}} \lambda (\ensuremath{D_{\text{fat}}^{d}}) &=& \int_{\Omega}\int_{[0,1]^{d}} 1_{\ensuremath{D_{\text{fat}}^{d}}}(x,\omega)d\lambda d\ensuremath{\mathbb{P}} \\
&=&  \int_{[0,1]^{d}}\int_{\Omega} 1_{\ensuremath{D_{\text{fat}}^{d}}}(x,\omega) d\ensuremath{\mathbb{P}} d\lambda\\
&=& \int_{[0,1]^{d}} \ensuremath{\mathbb{P}}(x \in \ensuremath{D_{\text{fat}}^{d}}) d\lambda = 0.
\end{eqnarray*}
 Therefore $\lambda(\ensuremath{D_{\text{fat}}^{d}})=0$ a.s. By Theorem \ref{thm12} we have $\lambda(\ensuremath{D_{\text{fat}}^{c}})> 0$ a.s.\ given non-extinction.

Next suppose that $\lambda(V)=1$. Then with a similar argument we can show that $\lambda(\ensuremath{D_{\text{fat}}^{c}})=0$ and $\lambda(\ensuremath{D_{\text{fat}}^{d}})>0$ a.s.\ given non-extinction. 
\end{proof}

